const schoolRows=ref([{id:'SCH-001',code:'DEMO-SCH-001',name:'星河实验小学（演示）',region:'华东 · 演示区域',year:'2026—2027',scope:'仅组织元数据',status:'正常'}, {id:'SCH-002',code:'DEMO-SCH-002',name:'向阳小学（演示）',region:'华南 · 演示区域',year:'2026—2027',scope:'尚未授权',status:'待确认'}]);
