const adminRows=ref([{id:'ADM-01',name:'op•••@wizzy.cn',role:'平台运营',scope:'脱敏元数据',mfa:'已开启',status:'正常'}, {id:'ADM-02',name:'model•••@wizzy.cn',role:'模型管理员',scope:'模型与评测配置',mfa:'已开启',status:'正常'}, {id:'ADM-03',name:'editor•••@wizzy.cn',role:'教材编辑',scope:'授权教材',mfa:'已开启',status:'正常'}]);
const auditRows=ref([{id:'AUD-104',time:'10/25 09:42',actor:'安全审计员',event:'授权元数据查看',resource:'SUP-204',basis:'家庭授权 · 已到期',status:'已记录'}, {id:'AUD-103',time:'10/24 16:08',actor:'模型管理员',event:'登记固定模型版本',resource:'MDL-019',basis:'EV-118',status:'已记录'}, {id:'AUD-102',time:'10/23 13:54',actor:'平台运营',event:'儿童内容访问',resource:'SUP-198',basis:'缺少家庭授权',status:'已拒绝'}]);
const rolePerms=ref(['租户元数据:读','任务元数据:读']),roleName=ref('平台运营'),evalRequested=ref(false),approvalRequested=ref(false);
const cols={people:[{key:'name',label:'学生标识',width:210},{key:'grade',label:'年级'},{key:'family',label:'所属家庭',width:160},{key:'guardian',label:'监护授权',width:170},{key:'status',label:'状态'}],schools:[{key:'name',label:'学校名称',width:240},{key:'region',label:'地区',width:170},{key:'year',label:'学年'},{key:'scope',label:'授权范围',width:170},{key:'status',label:'状态'}],books:[{key:'name',label:'教材名称',width:230},{key:'edition',label:'版本',width:180},{key:'pages',label:'总页数',width:90},{key:'mapping',label:'源页映射',width:120},{key:'status',label:'状态'}],models:[{key:'name',label:'模型 / 固定版本',width:220},{key:'provider',label:'供应商',width:160},{key:'version',label:'版本',width:180},{key:'accuracy',label:'批改正确率',width:230},{key:'status',label:'准入状态'}],tenants:[{key:'name',label:'家庭标识',width:210},{key:'students',label:'学生数',width:90},{key:'guardians',label:'监护人数',width:100},{key:'usage',label:'本月额度',width:160},{key:'storage',label:'存储用量'},{key:'status',label:'状态'}],jobs:[{key:'name',label:'任务 / 编号',width:210},{key:'tenant',label:'租户',width:170},{key:'stage',label:'当前阶段',width:150},{key:'time',label:'耗时',width:90},{key:'retry',label:'重试',width:100},{key:'status',label:'状态'}],admins:[{key:'name',label:'后台账号',width:240},{key:'role',label:'角色',width:160},{key:'scope',label:'数据范围',width:160},{key:'mfa',label:'MFA',width:120},{key:'status',label:'状态'}],audit:[{key:'time',label:'时间'},{key:'actor',label:'操作角色',width:140},{key:'event',label:'事件',width:200},{key:'resource',label:'资源'},{key:'basis',label:'授权依据',width:180},{key:'status',label:'结果'}]};
function log(event,resource){auditRows.value.unshift({id:'AUD-'+Date.now(),time:'10/25 · 本次演示',actor:'演示操作员',event,resource,basis:'原型会话 · 非生产审计',status:'已记录'});}
function openDetail(kind,row){evalRequested.value=false;approvalRequested.value=false;detailKind.value=kind;detail.value=row;drawer.value=true;}
function form(title,fields,save,note='',initial={}){Object.assign(dialog,{title,fields,save,note,initial,open:true});}
function saveForm(data){if(dialog.save(data)!==false)dialog.open=false;}
const field=(key,label,options)=>({key,label,required:true,...(options?{type:'select',options}:{})});
function add(type){
 const config={
 models:['登记模型版本',[field('name','模型名称'),field('provider','供应商'),field('version','固定版本标识'),field('purpose','用途',['数学封闭型题','文字结构化','交叉评测']),field('region','数据处理地域'),field('credential','服务端凭据引用（不是密钥）')],modelRows,{accuracy:'尚未评测',score:'—',status:'待评测',cost:'尚未统计'},'MDL','只登记元数据；不得粘贴 API Key。未通过质量和合规门禁，不可加入生产路由。'],
 schools:['新建学校档案',[field('name','学校名称'),field('code','唯一组织编码'),field('region','地区'),field('year','学年'),field('authorization','授权凭证编号')],schoolRows,{scope:'授权待核验',status:'待确认'},'SCH','登记组织不等于获得学生数据授权。'],
 people:['登记学生元数据',[field('name','学生脱敏标识'),field('family','家庭租户 ID'),field('grade','年级',['一年级','二年级','三年级','四年级','五年级','六年级'])],peopleRows,{guardian:'等待家庭授权',status:'待确认'},'stu','平台不代替监护人同意；保存不会自动绑定学生或开放作业访问。'],
 admins:['邀请后台账号',[{...field('name','工作邮箱'),email:true},field('role','角色',['平台运营','模型管理员','教材编辑','安全审计员']),field('scope','数据范围',['脱敏元数据','模型与评测配置','授权教材'])],adminRows,{mfa:'待开通',status:'待确认'},'ADM','演示只创建待邀请记录，不发送邮件；真实账号需受邀接受并启用 MFA 后方可访问。']};
 const c=config[type];form(c[0],c[1],data=>{if(type==='schools'&&schoolRows.value.some(s=>s.code===data.code)){ElMessage.error('组织编码已存在');return false;}c[2].value.unshift({...data,...c[3],id:c[4]+'-'+Date.now().toString().slice(-6)});log(c[0],data.name);ElMessage.success('已保存到本次演示会话');},c[5]);
}
function action(kind,a,row){
 if(a==='申请重试'){if(row.status!=='失败'){ElMessage.info('仅失败任务可以申请重试');return;}row.status='排队中';row.stage='等待重试';row.retry='3 / 3';log('申请任务重试',row.id);ElMessage.success('已模拟排入重试队列；未发起 AI 请求');return;}
 if(a==='调整权限'){openDetail('admins',row);return;}
 openDetail(kind,row);
}
function handleFile(e){const f=e.target.files[0];bookError.value='';if(!f)return;if(!/\.pdf$/i.test(f.name)||f.size>30*1024*1024){bookError.value='请选择不超过 30 MiB 的 PDF 文件';e.target.value='';return;}bookFile.value=f;bookName.value=f.name.replace(/\.pdf$/i,'');}
let parseTimer;
onBeforeUnmount(()=>clearInterval(parseTimer));
function startParse(){if(!bookFile.value||!rightBasis.value||!bookName.value.trim()){bookError.value='请先选择 PDF、填写教材名称并登记权利依据';return;}bookError.value='';bookStage.value='parsing';parseBusy.value=true;parseProgress.value=0;parseTimer=setInterval(()=>{parseProgress.value+=25;if(parseProgress.value>=100){clearInterval(parseTimer);parseBusy.value=false;bookStage.value='review';log('模拟教材解析',bookName.value);}},300);}
function submitBook(){bookRows.value.unshift({id:'BK-'+Date.now().toString().slice(-5),name:bookName.value,edition:'待审核版本',pages:'示例 3 页',mapping:'示例 3 / 3 页',rights:rightBasis.value,status:'待复核'});bookStage.value='submitted';log('提交教材抽检',bookName.value);ElMessage.success('已进入演示抽检队列，不代表解析真实 PDF 或已发布');}
function downloadText(){const text='小知 · 演示解析文本（并非所选 PDF 的提取结果）\n[chapter=长方形和正方形 source_page=1]\n长方形的周长 =（长 + 宽）× 2\n[chapter=示例练习 source_page=2]\n长8厘米，宽5厘米，周长是多少？\n[chapter=自检 source_page=3]\n请说明为什么要乘2。';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='wizzy-demo-extract.txt';a.click();URL.revokeObjectURL(a.href);}
function exportTenants(){const text='家庭标识,学生数,状态\n'+tenantRows.value.map(r=>`${r.id},${r.students},${r.status}`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));a.download='demo-tenant-metadata.csv';a.click();URL.revokeObjectURL(a.href);log('导出演示租户元数据','CSV');}
function importRoster(){form('名册导入 · 行校验演示',[{key:'rows',label:'粘贴脱敏名册（每行：学号,年级）',type:'textarea',required:true,max:5000}],data=>{const lines=data.rows.trim().split('\n').map(s=>s.split(',').map(v=>v.trim()));if(lines.some(r=>r.length!==2||!r[0]||peopleRows.value.some(p=>p.id===r[0])||!/^[一二三四五六]年级$/.test(r[1].trim()))||new Set(lines.map(r=>r[0])).size!==lines.length){ElMessage.error('校验失败：请检查重复学号和年级格式；未导入任何记录');return false;}lines.forEach(r=>peopleRows.value.push({id:r[0].trim(),name:'学生 '+r[0].trim(),grade:r[1].trim(),family:'尚未关联',guardian:'等待家庭授权',status:'待确认'}));log('模拟名册校验',`${lines.length} 行`);ElMessage.success(`校验通过，新增 ${lines.length} 条待授权元数据`);},'示例：DEMO-001,三年级。只接受虚构信息，未授权记录不会绑定到家庭。');}
</script>
<template><PageHead eyebrow="WORKSPACE / PLATFORM" :title="names[0]" :description="names[1]"><template v-if="tab==='ops'"><span class="live-status"><i/>服务运行正常</span><el-button @click="ElMessage.success('演示快照已刷新；未查询真实服务')"><Icon name="refresh" :size="16"/>刷新快照</el-button></template><el-button v-if="['models','people','schools','admins'].includes(tab)" type="primary" @click="add(tab)"><Icon name="plus" :size="17"/>{{{models:'登记模型',people:'登记学生',schools:'新建学校',admins:'邀请账号'}[tab]}}</el-button><el-button v-if="tab==='tenants'" @click="exportTenants"><Icon name="download" :size="17"/>导出元数据</el-button><el-button v-if="tab==='schools'" @click="importRoster"><Icon name="upload" :size="17"/>名册校验</el-button></PageHead>
