jobs[0],cols.jobs[2],cols.jobs[5]]" @action="(a,r)=>openDetail('jobs',r)"/></section><section class="panel action-center"><div class="panel-head"><h2>待办与提醒</h2><span class="number-badge">3</span></div><button v-for="x in [['library','教材抽检','1 份解析稿等待版权与质量复核','books'],['cpu','模型准入','1 个固定版本等待独立复核','models'],['lock','权限变更','1 项变更等待安全员审批','admins']]" :key="x[3]" @click="emit('navigate',x[3])"><span class="soft-icon blue"><Icon :name="x[0]"/></span><span><strong>{{x[1]}}</strong><small>{{x[2]}}</small></span><Icon name="right" :size="17"/></button><div class="inline-note"><Icon name="shield" :size="17"/>所有生产变更需独立审批，演示不可发布。</div></section></div></template>
<template v-else-if="tab==='models'"><div class="info-banner"><span class="soft-icon blue"><Icon name="shield"/></span><div><strong>质量来自可复现评测，不来自模型自报置信度</strong><p>固定版本 + 锁定测试集 + 人工金标准。家长改判只进入候选样本，不能直接作为评分依据。</p></div><el-tag type="info">全部分值为示例</el-tag></div><div class="metric-grid three"><article class="metric-card"><div class="metric-top">模型版本<span class="soft-icon blue"><Icon name="cpu"/></span></div><div class="metric-value">{{modelRows.length}}<small>个</small></div><p>登记不等于准入生产路由</p></article><article class="metric-card"><div class="metric-top">标准版批改正确率<span class="soft-icon mint"><Icon name="target"/></span></div><div class="metric-value">95.2<small>%</small></div><p>自动判定正确 476 / 500 · 低于 99% 准入点估计</p></article><article class="metric-card"><div class="metric-top">锁定评测集<span class="soft-icon violet"><Icon name="lock"/></span></div><div class="metric-value code-value">EV-2026-10-r3</div><p>数学封闭型题 · 不外推其他题型</p></article></div><section class="panel"><el-tabs v-model="subtab"><el-tab-pane label="模型目录" name="directory"><DataGrid :rows="modelRows" :columns="cols.models" :status-options="['未达准入','待复核','评测中','待评测']" :actions="['版本详情','评测报告']" @action="(a,r)=>{evalRequested=false;approvalRequested=false;openDetail(a==='评测报告'?'evaluation':'models',r)}"/></el-tab-pane><el-tab-pane label="评分与准入规则" name="rules"><div class="rules-grid"><article><h3>评分口径</h3><p>演示评分 = 自动判定正确题数 / 自动判定题数 × 100。待确认单独计数；具体覆盖率和正确率按评测协议同时报告。</p><p>必须同时披露误判正确率、错杀率、题型分层、样本量和置信区间。OCR 不能与判题模型混在同一榜单。</p></article><article><h3>发布门禁</h3><el-steps direction="vertical" :active="1"><el-step title="固定版本与隐私合同"/><el-step title="独立锁定集质量评测"/><el-step title="质量 / 安全独立审批"/><el-step title="小流量灰度与回滚演练"/></el-steps></article></div><el-alert title="准确率示例不代表已达标；真实门禁以 04 / 11 文档为准。样本不足不可判定通过。" type="warning" :closable="false" show-icon/></el-tab-pane></el-tabs></section></template>
<template v-else-if="tab==='books'"><div class="split-books"><section class="panel book-workflow"><div class="panel-head"><div><h2>新增教材解析任务</h2><p>原文件仅本地选择，解析结果是固定示例</p></div><span class="soft-icon blue"><Icon name="file"/></span></div><el-steps :active="bookStage==='upload'?0:bookStage==='parsing'?1:bookStage==='review'?2:3" finish-status="success" align-center><el-step title="授权与文件"/><el-step title="模拟解析"/><el-step title="检查与抽检"/></el-steps><template v-if="bookStage==='upload'"><button class="upload-zone" @click="fileInput.click()"><span class="upload-symbol"><Icon name="upload" :size="30"/></span><strong>{{bookFile?bookFile.name:'选择教材 PDF'}}</strong><span>PDF · 最大 30 MiB · 请使用自有或已获授权内容</span><span class="pseudo-button">{{bookFile?'重新选择':'选择文件'}}</span></button><input ref="fileInput" type="file" accept=".pdf,application/pdf" class="sr-only" aria-label="选择教材PDF" @change="handleFile"/><el-form label-position="top"><el-form-item label="教材名称" required><el-input v-model="bookName" placeholder="如：数学 · 三年级上册" maxlength="80"/></el-form-item><el-form-item label="内容权利依据" required><el-select v-model="rightBasis" placeholder="请选择权利依据"><el-option v-for="v in ['自有原创内容','已取得出版方授权','仅限合法内部评测授权']" :key="v" :value="v" :label="v"/></el-select></el-form-item></el-form><el-alert v-if="bookError" :title="bookError" type="error" :closable="false"/><el-button type="primary" class="full-button" @click="startParse"><Icon name="sparkles" :size="17"/>开始模拟解析</el-button></template><template v-else-if="bookStage==='parsing'"><div class="parse-progress"><Icon name="file" :size="48"/><h3>正在演示解析阶段</h3><el-progress :percentage="parseProgress"/><p>仅播放本地阶段动画，未读取或 OCR 所选文件。</p></div></template><template v-else-if="bookStage==='review'"><div class="parse-result"><span class="soft-icon mint"><Icon name="check"/></span><div><h3>演示解析稿已就绪</h3><p>固定示例 3 页 · 3 个源页映射 · 尚未发布</p></div></div><pre class="text-preview">[chapter=长方形和正方形 source_page=1]
长方形的周长 =（长 + 宽）× 2

[chapter=示例练习 source_page=2]
长8厘米，宽5厘米，周长是多少？

[chapter=自检 source_page=3]
请说明为什么要乘2。</pre><div class="button-row"><el-button @click="downloadText"><Icon name="download" :size="16"/>下载示例 TXT</el-button><el-button type="primary" @click="submitBook">提交抽检</el-button></div><p class="muted">这不是所选 PDF 的真实提取结果。真实发布需核验授权、抽检字迹和源页映射。</p></template><el-result v-else icon="success" title="已进入演示抽检队列" sub-title="教材状态为待复核，未发布。"><template #extra><el-button @click="bookStage='upload';bookFile=null;bookName=''">继续添加教材</el-button></template></el-result></section><section class="panel"><div class="panel-head"><div><h2>质量与权利检查</h2><p>发布前必须逐项确认</p></div></div><div v-for="(t,i) in ['授权主体、地域与有效期','目录、章节和源 PDF 页码映射','公式、表格与手写文字抽检','缺页 / 低质量页返工','审核人独立复核与版本发布']" :key="t" class="checklist-row"><span>{{i+1}}</span><div>{{t}}</div><Icon name="lock" :size="16"/></div><div class="inline-note"><Icon name="shield"/>原型不提供一键发布，避免绕过权利和质量门禁。</div></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>教材资源库</h2><p>保留原文件版本、提取文本、授权依据和源页引用</p></div></div><DataGrid :rows="bookRows" :columns="cols.books" :status-options="['已发布','待复核']" @action="(a,r)=>openDetail('books',r)"/></section></template>
<template v-else-if="tab==='admins'"><div class="info-banner"><span class="soft-icon violet"><Icon name="lock"/></span><div><strong>前端隐藏按钮不是权限控制</strong><p>生产后端必须逐请求校验角色、数据范围和有效会话。模型发布、敏感访问与权限提升需独立审批。</p></div></div><section class="panel"><div class="panel-head"><div><h2>后台账号</h2><p>邀请待接受、MFA 未开启的账号不能登录生产后台</p></div></div><DataGrid :rows="adminRows" :columns="cols.admins" :actions="['调整权限']" @action="(a,r)=>openDetail('admins',r)"/></section><section class="panel section-gap"><div class="panel-head"><div><h2>角色权限矩阵</h2><p>保存后仅创建待审批变更，不立即生效</p></div><el-select v-model="roleName" aria-label="角色模板"><el-option v-for="r in ['平台运营','模型管理员','教材编辑','安全审计员']" :key="r" :value="r"/></el-select></div><el-checkbox-group v-model="rolePerms" class="permissions-grid"><el-checkbox v-for="p in ['租户元数据:读','任务元数据:读','模型登记:写','模型评测:执行','教材草稿:写','授权抽检:审核','后台账号:邀请','审计日志:读']" :key="p" :value="p" :label="p" border/></el-checkbox-group><div class="panel-bottom"><span class="muted">不会授予儿童原图访问权限；申请人与审批人必须不同。</span><el-button type="primary" @click="log('提交角色权限变更',roleName);ElMessage.success('权限变更已模拟提交独立审批，尚未生效')">提交独立审批</el-button></div></section></template>
<template v-else><div v-if="tab==='people'||tab==='tenants'" class="info-banner"><span class="soft-icon blue"><Icon name="shield"/></span><div><strong>当前为脱敏元数据视图</strong><p>学生用标识码展示。查看儿童内容必须另有家庭授权、限时工单及完整审计。</p></div></div><div v-if="tab==='jobs'" class="queue-summary"><span><i class="service-dot"/>执行中 <strong>8</strong></span><span><i class="service-dot warning"/>排队 <strong>4</strong></span><span>最大重试 <strong>3 次</strong></span><span>幂等键防重复计费</span></div><section class="panel"><div class="panel-head"><div><h2>{{{tenants:'家庭租户目录',jobs:'处理任务',people:'学生与监护关系',schools:'学校档案',audit:'操作与访问记录'}[tab]}}</h2><p>记录均为虚构示例，新增和变更仅保留在本次会话</p></div><el-tag v-if="tab==='schools'" type="warning">P1 · 需范围确认</el-tag></div><DataGrid :key="tab" :rows="{tenants:tenantRows,jobs:jobRows,people:peopleRows,schools:schoolRows,audit:auditRows}[tab]||[]" :columns="cols[tab]||[]" :actions="tab==='jobs'?['查看详情','申请重试']:['查看详情']" :status-options="{tenants:['正常','待确认'],jobs:['处理中','排队中','失败','已完成'],people:['已绑定','待确认'],schools:['正常','待确认'],audit:['已记录','已拒绝']}[tab]" @action="(a,r)=>action(tab,a,r)"/></section><div class="inline-note section-gap"><Icon name="shield" :size="18"/>{{tab==='audit'?'审计日志不复制原图、答案或儿童姓名；拒绝事件同样留痕。':'组织授权、监护授权和平台角色不能互相替代。所有写入均需服务端权限校验。'}}</div></template>
<el-drawer v-model="drawer" :title="detailKind==='evaluation'?'模型质量评测报告':detailKind==='admins'?'账号权限变更': '记录详情'" size="min(650px, 100%)"><div class="detail-identity"><span class="soft-icon blue"><Icon :name="{models:'cpu',evaluation:'target',books:'library',jobs:'activity',admins:'lock'}[detailKind]||'file'" :size="26"/></span><div><h2>{{detail.name||detail.event||detail.id}}</h2><span class="mono muted">{{detail.id}}</span></div><el-tag>{{detail.status}}</el-tag></div><template v-if="detailKind==='evaluation'||detailKind==='models'"><el-alert title="演示报告 · 不代表任何真实供应商质量或准入结论" type="warning" :closable="false" show-icon/><el-descriptions :column="1" border class="section-gap"><el-descriptions-item label="固定版本">{{detail.version}}</el-descriptions-item><el-descriptions-item label="评测集">EV-2026-10-r3 · 锁定版本</el-descriptions-item><el-descriptions-item label="人工金标准">双人独立标注 + 仲裁（示例）</el-descriptions-item><el-descriptions-item label="批改正确率">{{detail.accuracy}}</el-descriptions-item><el-descriptions-item label="评分">{{detail.score||'尚未评分'}}</el-descriptions-item><el-descriptions-item label="正确率口径">自动判定正确题数 / 自动判定题数；待确认不计入错误</el-descriptions-item><el-descriptions-item label="覆盖率与置信区间">独立报告覆盖率；真实评测需计算单侧 95% 置信下界</el-descriptions-item><el-descriptions-item label="误判正确率">误判正确题数 / 金标准错误题总数；单侧 95% 置信上界 ≤ 1%</el-descriptions-item><el-descriptions-item label="准入结论">正确率点估计及单侧 95% 下界均须 ≥ 99%；示例标准版 95.2% 不达标</el-descriptions-item></el-descriptions><h3 class="section-gap">质量与合规发布路径</h3><el-timeline><el-timeline-item type="primary" timestamp="版本登记">固定版本，禁止浮动别名自动上线</el-timeline-item><el-timeline-item timestamp="锁定集评测">按题型报告正确率、覆盖率与置信区间</el-timeline-item><el-timeline-item timestamp="独立审批">教研质量、安全与隐私审批</el-timeline-item><el-timeline-item timestamp="受控灰度">预算上限、停止条件与回滚版本</el-timeline-item></el-timeline><div class="button-row"><el-button :disabled="evalRequested" type="primary" @click="evalRequested=true;log('申请模型评测',detail.id);ElMessage.success('已模拟创建评测申请，未调用模型')">{{evalRequested?'评测申请已登记':'申请评测'}}</el-button><el-button :disabled="approvalRequested" @click="approvalRequested=true;log('提交模型准入复核',detail.id);ElMessage.success('已提交演示复核，生产路由未变更')">{{approvalRequested?'已提交复核':'提交准入复核'}}</el-button></div></template><template v-else-if="detailKind==='admins'"><el-descriptions :column="1" border><el-descriptions-item label="当前角色">{{detail.role}}</el-descriptions-item><el-descriptions-item label="当前范围">{{detail.scope}}</el-descriptions-item><el-descriptions-item label="MFA">{{detail.mfa}}</el-descriptions-item></el-descriptions><h3>申请调整角色</h3><el-select v-model="roleName" aria-label="目标角色"><el-option v-for="v in ['平台运营','模型管理员','教材编辑','安全审计员']" :key="v" :value="v"/></el-select><el-alert title="演示提交只增加审批记录，不修改有效权限。MFA 重置需另外验证身份。" type="info" :closable="false" class="section-gap"/><el-button type="primary" class="section-gap" @click="log('账号角色变更申请',detail.id+' → '+roleName);drawer=false;ElMessage.success('已模拟提交审批，当前权限不变')">提交角色变更审批</el-button></template><template v-else><el-descriptions :column="1" border><el-descriptions-item v-for="(value,key) in detail" :key="key" :label="({name:'名称',id:'记录编号',status:'状态',stage:'处理阶段',time:'耗时 / 时间',retry:'重试次数',tenant:'租户',region:'地区',scope:'授权范围',year:'学年',grade:'年级',family:'家庭',guardian:'监护授权',edition:'教材版本',pages:'页数',rights:'权利依据',mapping:'页码映射',students:'学生数',guardians:'监护人数',storage:'存储',usage:'用量',actor:'操作角色',event:'事件',resource:'资源',basis:'依据'})[key]||key">{{value}}</el-descriptions-item></el-descriptions><template v-if="detailKind==='jobs'"><h3 class="section-gap">处理阶段</h3><el-steps direction="vertical" :active="detail.status==='已完成'?4:detail.status==='失败'?1:2" :process-status="detail.status==='失败'?'error':'process'"><el-step title="接收任务" description="以幂等键关联，不重复创建账单"/><el-step title="图像识别" description="供应商超时只记录错误码，不复制内容"/><el-step title="规则检查"/><el-step title="结果可用"/></el-steps></template><template v-if="detailKind==='books'"><h3 class="section-gap">源页映射示例</h3><div class="mapping-row"><span>长方形和正方形</span><strong>PDF p.1 → TXT 第 1 节</strong></div><el-button @click="downloadText">下载示例 TXT</el-button></template><div class="inline-note section-gap"><Icon name="shield"/>不展示儿童原图和答案。操作需服务端再次鉴权，当前仅为交互演示。</div></template></el-drawer><FormDialog v-model="dialog.open" :title="dialog.title" :fields="dialog.fields" :note="dialog.note" :initial="dialog.initial" @save="saveForm"/>
</template>
